<?php
/** Responsible AI: bias and fairness, privacy, copyright, the EU AI Act, everyday habits, labelling generated content, automated decisions and rights, impact on environment and work. */

if (!function_exists('fig_aiethics_pyramid')) {
    function fig_aiethics_pyramid(string $t1, string $t1e, string $t1d, string $t2, string $t2e, string $t2d, string $t3, string $t3e, string $t3d, string $t4, string $t4e, string $t4d): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 330" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><path d="M150 20H230L264 92H116z" fill="#FFE3EE" stroke="#F03E82" stroke-width="2" stroke-linejoin="round"/><text x="190" y="62" text-anchor="middle" font-weight="700" font-size="14" fill="#C2185B">{$t1}</text><line x1="258" y1="56.0" x2="384" y2="56.0" stroke="#F03E82" stroke-width="2" stroke-dasharray="3 3"/><text x="392" y="50" font-size="14" font-weight="700" fill="#C2185B">{$t1d}</text><text x="392" y="72" font-size="13">{$t1e}</text><path d="M116 96H264L298 168H82z" fill="#FFE8D6" stroke="#E8590C" stroke-width="2" stroke-linejoin="round"/><text x="190" y="138" text-anchor="middle" font-weight="700" font-size="14" fill="#B84508">{$t2}</text><line x1="292" y1="132.0" x2="384" y2="132.0" stroke="#E8590C" stroke-width="2" stroke-dasharray="3 3"/><text x="392" y="126" font-size="14" font-weight="700" fill="#B84508">{$t2d}</text><text x="392" y="148" font-size="13">{$t2e}</text><path d="M82 172H298L332 244H48z" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2" stroke-linejoin="round"/><text x="190" y="214" text-anchor="middle" font-weight="700" font-size="14" fill="#1B66BC">{$t3}</text><line x1="326" y1="208.0" x2="384" y2="208.0" stroke="#2F8CF0" stroke-width="2" stroke-dasharray="3 3"/><text x="392" y="202" font-size="14" font-weight="700" fill="#1B66BC">{$t3d}</text><text x="392" y="224" font-size="13">{$t3e}</text><path d="M48 248H332L366 320H14z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2" stroke-linejoin="round"/><text x="190" y="290" text-anchor="middle" font-weight="700" font-size="14" fill="#0B7F5C">{$t4}</text><line x1="360" y1="284.0" x2="384" y2="284.0" stroke="#0B7F5C" stroke-width="2" stroke-dasharray="3 3"/><text x="392" y="278" font-size="14" font-weight="700" fill="#0B7F5C">{$t4d}</text><text x="392" y="300" font-size="13">{$t4e}</text></svg>
SVG;
    }
}

if (!function_exists('fig_aiethics_groups')) {
    function fig_aiethics_groups(string $all, string $ga, string $gb, string $gbn, string $xaxis, string $note): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 290" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><line x1="200" y1="30" x2="200" y2="210" stroke="#8A87B0" stroke-width="2"/><line x1="200" y1="30" x2="200" y2="210" stroke="#ECEBF5" stroke-width="1"/><text x="200" y="230" text-anchor="middle" font-size="13" fill="#5E5B85">50%</text><line x1="280" y1="30" x2="280" y2="210" stroke="#ECEBF5" stroke-width="1"/><text x="280" y="230" text-anchor="middle" font-size="13" fill="#5E5B85">60%</text><line x1="360" y1="30" x2="360" y2="210" stroke="#ECEBF5" stroke-width="1"/><text x="360" y="230" text-anchor="middle" font-size="13" fill="#5E5B85">70%</text><line x1="440" y1="30" x2="440" y2="210" stroke="#ECEBF5" stroke-width="1"/><text x="440" y="230" text-anchor="middle" font-size="13" fill="#5E5B85">80%</text><line x1="520" y1="30" x2="520" y2="210" stroke="#ECEBF5" stroke-width="1"/><text x="520" y="230" text-anchor="middle" font-size="13" fill="#5E5B85">90%</text><line x1="600" y1="30" x2="600" y2="210" stroke="#ECEBF5" stroke-width="1"/><text x="600" y="230" text-anchor="middle" font-size="13" fill="#5E5B85">100%</text><text x="188" y="64" text-anchor="end" font-size="14" font-weight="700">{$all}</text><rect x="200" y="44" width="352" height="32" rx="6" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="542" y="65" text-anchor="end" font-size="14" font-weight="700" fill="#1B66BC">94%</text><text x="188" y="120" text-anchor="end" font-size="14" font-weight="700">{$ga}</text><rect x="200" y="100" width="368" height="32" rx="6" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="558" y="121" text-anchor="end" font-size="14" font-weight="700" fill="#0B7F5C">96%</text><text x="188" y="176" text-anchor="end" font-size="14" font-weight="700">{$gb}</text><rect x="200" y="156" width="224" height="32" rx="6" fill="#FFE3EE" stroke="#F03E82" stroke-width="2"/><text x="414" y="177" text-anchor="end" font-size="14" font-weight="700" fill="#C2185B">78%</text><text x="188" y="200" text-anchor="end" font-size="12" fill="#5E5B85">{$gbn}</text><text x="320" y="262" text-anchor="middle" font-size="14">{$xaxis}</text><text x="320" y="282" text-anchor="middle" font-size="12" fill="#5E5B85">{$note}</text></svg>
SVG;
    }
}

return [
    'id' => 'ai-ethics', 'family' => 'ai', 'after' => 'ai-base',
    'title' => L('AI responsabile e privacy', 'Responsible AI and Privacy'), 'short' => L('AI responsabile', 'Responsible AI'), 'level' => L('Base', 'Basics'),
    'desc' => L('Usare l’AI senza fare danni: bias ed equità, dati personali, diritto d’autore, AI Act europeo, buone abitudini, etichette sui contenuti generati, decisioni automatiche e diritti, impatto su ambiente e lavoro.', 'Using AI without causing harm: bias and fairness, personal data, copyright, the EU AI Act, good habits, labels on generated content, automated decisions and rights, impact on environment and work.'),
    'lessons' => [
        lesson('bias', L('Bias ed equità', 'Bias and fairness'), [
            P('Un modello impara dai dati, compresi i loro **pregiudizi**. Se in passato un’azienda ha assunto soprattutto uomini, un modello addestrato su quei curriculum può penalizzare le donne. Questo è un **bias**: un errore sistematico che svantaggia un gruppo.', 'A model learns from data, prejudices included. If a company mostly hired men in the past, a model trained on those CVs may penalise women. That is a **bias**: a systematic error that disadvantages a group.'),
            P('Il bias si nasconde nelle medie. Un modello può essere giusto il 94% delle volte nel complesso e solo il 78% per un gruppo che è il 12% dei dati: il gruppo grande alza la media e copre il problema. Per questo l’accuratezza va sempre controllata **gruppo per gruppo** (età, genere, provenienza, lingua). Un errore frequente è pensare che basti togliere la colonna «genere»: il modello può ricostruirlo da altri dati, come il nome o il tipo di lavoro.', 'Bias hides in averages. A model can be right 94% of the time overall and only 78% for a group that makes up 12% of the data: the large group lifts the average and covers the problem. That is why accuracy must always be checked **group by group** (age, gender, origin, language). A common mistake is thinking it is enough to drop the “gender” column: the model can rebuild it from other data, such as the first name or the type of job.'),
            Fig(L(fig_aiethics_groups('tutti', 'gruppo A', 'gruppo B', '12% dei dati', 'accuratezza', 'Dati illustrativi: la media alta nasconde l’errore sul gruppo piccolo.'), fig_aiethics_groups('everyone', 'group A', 'group B', '12% of the data', 'accuracy', 'Illustrative data: the high average hides the error on the small group.')),
                L('Tre barre orizzontali di accuratezza: tutti 94 per cento, gruppo A 96 per cento, gruppo B, che è il 12 per cento dei dati, solo 78 per cento.', 'Three horizontal accuracy bars: everyone 94 per cent, group A 96 per cent, group B, which is 12 per cent of the data, only 78 per cent.'),
                L('Una buona media può nascondere un gruppo trattato male.', 'A good average can hide a group that is treated badly.')),
            P('Le difese: dati rappresentativi, misurare gli errori **per gruppo** (non solo in media), togliere variabili sensibili *e* quelle che le sostituiscono (il CAP può rivelare l’origine), e tenere una persona nel giro per le decisioni importanti.', 'Defences: representative data, measuring errors **per group** (not just on average), removing sensitive variables *and* their proxies (a postcode can reveal origin), and keeping a person in the loop for important decisions.'),
        ], [
            Q('b1', L('Da dove nasce più spesso un bias?', 'Where does bias most often come from?'), [L('Dai dati di addestramento', 'From the training data'), L('Dal colore del logo', 'From the logo colour'), L('Dalla velocità del server', 'From server speed'), L('Dal numero di utenti', 'From the number of users')], 0, L('Il modello riflette i dati.', 'The model mirrors the data.')),
            Q('b2', L('Perché misurare gli errori per gruppo?', 'Why measure errors per group?'), [L('Una buona media può nascondere un gruppo svantaggiato', 'A good average can hide a disadvantaged group'), L('Per fare più grafici', 'To make more charts'), L('È più veloce', 'It is faster'), L('Non serve', 'It is not needed')], 0, L('L’equità si vede nei dettagli.', 'Fairness shows in the details.')),
            Q('b3', L('Che cos’è una variabile “proxy”?', 'What is a “proxy” variable?'), [L('Una che rivela indirettamente un dato sensibile', 'One that indirectly reveals a sensitive attribute'), L('Un server intermedio', 'An intermediate server'), L('Una password', 'A password'), L('Un tipo di grafico', 'A type of chart')], 0, L('Per esempio il CAP.', 'For example the postcode.')),
        ], task('text', L('Elenca due modi per ridurre il bias, uno per riga, che inizino con `-`.', 'List two ways to reduce bias, one per line, starting with `-`.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due misure', 'Two measures')), re('dati|data|grupp|group|umano|human|person', L('Parli di dati, gruppi o controllo umano', 'You mention data, groups or human oversight'))], '', "- usare dati rappresentativi di tutti i gruppi\n- misurare gli errori separatamente per ogni gruppo"), [
            dMatch(pMatch(), [['Bias', L('Errore sistematico verso un gruppo', 'Systematic error against a group')], ['Proxy', L('Variabile che rivela un dato sensibile', 'Variable revealing a sensitive attribute')], [L('Dati rappresentativi', 'Representative data'), L('Tutti i gruppi presenti', 'All groups present')], [L('Persona nel giro', 'Human in the loop'), L('Decide nei casi importanti', 'Decides important cases')]], L('Il lessico dell’equità.', 'The vocabulary of fairness.')),
            dFlash(pFlash(), [[L('Un modello può essere ingiusto senza che nessuno lo voglia', 'A model can be unfair without anyone intending it'), true], [L('Togliere il campo “genere” elimina sempre il bias', 'Removing the “gender” field always removes bias'), false], [L('Una buona accuratezza media basta', 'Good average accuracy is enough'), false], [L('I dati storici possono contenere discriminazioni', 'Historical data can contain discrimination'), true]], L('L’equità va misurata.', 'Fairness must be measured.')),
        ]),
        lesson('privacy', L('Dati personali e privacy', 'Personal data and privacy'), [
            P('Quello che scrivi in un chatbot può essere conservato, letto per sicurezza o, secondo le impostazioni, usato per addestrare modelli futuri. Prima di incollare dati, controlla la **policy** del servizio e le impostazioni di privacy.', 'What you type into a chatbot may be stored, reviewed for safety or, depending on settings, used to train future models. Before pasting data, check the service’s **policy** and privacy settings.'),
            P('Non inserire dati personali di altri, password, dati sanitari o segreti aziendali in servizi non approvati. In Europa vale il **GDPR**: servono una base legale, il minimo indispensabile di dati e trasparenza verso le persone coinvolte. Quando puoi, **anonimizza** (togli nomi, email, numeri).', 'Do not enter other people’s personal data, passwords, health data or company secrets into unapproved services. In Europe the **GDPR** applies: you need a legal basis, the minimum necessary data and transparency towards the people involved. When you can, **anonymise** (remove names, emails, numbers).'),
        ], [
            Q('p1', L('Che cosa non andrebbe incollato in un chatbot pubblico?', 'What should not be pasted into a public chatbot?'), [L('La password di un collega', 'A colleague’s password'), L('Una ricetta della nonna', 'Grandma’s recipe'), L('Una poesia di Leopardi', 'A Leopardi poem'), L('Un esercizio di matematica', 'A maths exercise')], 0, L('Segreti e dati altrui restano fuori.', 'Secrets and others’ data stay out.')),
            Q('p2', L('Che cosa significa anonimizzare?', 'What does anonymising mean?'), [L('Togliere ciò che identifica le persone', 'Removing what identifies people'), L('Cifrare il computer', 'Encrypting the computer'), L('Cambiare nome utente', 'Changing username'), L('Usare la modalità scura', 'Using dark mode')], 0, L('Nomi, email, numeri, indirizzi.', 'Names, emails, numbers, addresses.')),
            Q('p3', L('Quale principio chiede il GDPR?', 'Which principle does the GDPR require?'), [L('Usare il minimo di dati necessario', 'Using the minimum data necessary'), L('Raccogliere più dati possibile', 'Collecting as much data as possible'), L('Pubblicare i dati', 'Publishing the data'), L('Nessuna regola', 'No rules')], 0, L('Minimizzazione dei dati.', 'Data minimisation.')),
        ], task('text', L('Anonimizza questo testo sostituendo nome, email e telefono con `[NOME]`, `[EMAIL]` e `[TELEFONO]`: “Mario Rossi (mario.rossi@example.com, 333 1234567) chiede un rimborso.”', 'Anonymise this text replacing name, email and phone with `[NOME]`, `[EMAIL]` and `[TELEFONO]`: “Mario Rossi (mario.rossi@example.com, 333 1234567) asks for a refund.”'), 'Mario Rossi (mario.rossi@example.com, 333 1234567) chiede un rimborso.', [re('\[NOME\]', L('Il nome è nascosto', 'The name is hidden')), re('\[EMAIL\]', L('L’email è nascosta', 'The email is hidden')), re('\[TELEFONO\]', L('Il telefono è nascosto', 'The phone is hidden')), re('(?<![\s\S])(?![\s\S]*(Rossi|@example|1234567))', L('Non resta nessun dato originale', 'No original data is left'))], '', '[NOME] ([EMAIL], [TELEFONO]) chiede un rimborso.'), [
            dBug(pBug(), ['reclamo = {', '  cliente: "[NOME]",', '  email: "[EMAIL]",', '  carta: "4111 1111 1111 1111",', '  problema: "pacco mai arrivato"', '}'], 3, '  carta: "[CARTA]",', L('Il numero di carta va tolto prima di incollare.', 'The card number must be removed before pasting.')),
            dFlash(pFlash(), [[L('Alcuni servizi usano le chat per addestrare i modelli', 'Some services use chats to train models'), true], [L('Incollare dati sanitari altrui è sempre lecito', 'Pasting others’ health data is always fine'), false], [L('Conviene leggere le impostazioni di privacy', 'It pays to read the privacy settings'), true], [L('Il GDPR non riguarda l’AI', 'The GDPR does not apply to AI'), false]], L('I dati delle persone vanno protetti.', 'People’s data must be protected.')),
        ]),
        lesson('copyright', L('Diritto d’autore e originalità', 'Copyright and originality'), [
            P('Chi possiede un testo o un’immagine generati dall’AI? Le regole variano da paese a paese e stanno ancora cambiando. In molti ordinamenti un’opera è protetta solo se c’è un **contributo creativo umano** significativo.', 'Who owns a text or image generated by AI? The rules vary by country and are still evolving. In many legal systems a work is protected only when there is a significant **human creative contribution**.'),
            P('Buone pratiche: non chiedere di copiare opere protette o lo stile riconoscibile di un artista vivente per scopi commerciali, controlla le **condizioni d’uso** del servizio, verifica che il codice generato non riproduca codice con licenze incompatibili, e dichiara l’uso dell’AI quando è richiesto (scuola, editori, concorsi).', 'Good practice: do not ask to copy protected works or a living artist’s recognisable style for commercial use, check the service’s **terms of use**, verify generated code does not reproduce code under incompatible licences, and disclose AI use when required (school, publishers, contests).'),
        ], [
            Q('r1', L('In molti paesi, quando un’opera generata è protetta?', 'In many countries, when is a generated work protected?'), [L('Se c’è un contributo creativo umano', 'When there is human creative contribution'), L('Sempre', 'Always'), L('Mai, in nessun caso', 'Never, in any case'), L('Solo se è lunga', 'Only if it is long')], 0, L('E le regole cambiano ancora.', 'And the rules are still changing.')),
            Q('r2', L('Che cosa controllare nel codice generato?', 'What should you check in generated code?'), [L('Che non copi codice con licenze incompatibili', 'That it does not copy code with incompatible licences'), L('Che abbia tanti commenti', 'That it has many comments'), L('Che sia colorato', 'That it is colourful'), L('Niente', 'Nothing')], 0, L('Le licenze contano anche per l’AI.', 'Licences matter for AI too.')),
            Q('r3', L('Quando dichiarare l’uso dell’AI?', 'When should you disclose AI use?'), [L('Quando è richiesto da scuola, editore o regolamento', 'When school, publisher or rules require it'), L('Mai', 'Never'), L('Solo il lunedì', 'Only on Mondays'), L('Solo per le immagini', 'Only for images')], 0, L('La trasparenza evita problemi.', 'Transparency avoids trouble.')),
        ], task('text', L('Scrivi una breve nota di trasparenza (una o due frasi) da mettere in fondo a un articolo scritto con l’aiuto dell’AI e rivisto da te.', 'Write a short transparency note (one or two sentences) to put at the end of an article written with AI help and reviewed by you.'), '', [re('\bAI\b|\bIA\b|intelligenza artificiale|artificial intelligence', L('Citi l’AI', 'You mention AI')), re('rivist|revisionat|controllat|verificat|review|checked|edited', L('Dici che l’hai rivisto', 'You say you reviewed it'))], '', 'Questo articolo è stato scritto con l’aiuto di uno strumento di AI e rivisto e verificato dall’autore.'), [
            dMatch(pMatch(), [[L('Contributo umano', 'Human contribution'), L('Base della tutela', 'Basis for protection')], [L('Condizioni d’uso', 'Terms of use'), L('Cosa permette il servizio', 'What the service allows')], [L('Licenza', 'Licence'), L('Regole d’uso del codice', 'Rules for using code')], [L('Nota di trasparenza', 'Transparency note'), L('Dichiara l’uso dell’AI', 'Discloses AI use')]], L('Creare con l’AI in modo corretto.', 'Creating with AI correctly.')),
            dFlash(pFlash(), [[L('Le regole sul diritto d’autore e l’AI sono uguali ovunque', 'Copyright rules on AI are the same everywhere'), false], [L('Il codice generato può riprodurre codice esistente', 'Generated code can reproduce existing code'), true], [L('Le condizioni d’uso del servizio contano', 'The service’s terms of use matter'), true], [L('Dichiarare l’uso dell’AI è vietato', 'Disclosing AI use is forbidden'), false]], L('Trasparenza e rispetto.', 'Transparency and respect.')),
        ]),
        lesson('ai-act', L('L’AI Act europeo', 'The EU AI Act'), [
            P('L’**AI Act** è il regolamento europeo sull’intelligenza artificiale, entrato in vigore nel 2024 e applicato a tappe: i divieti valgono dal febbraio 2025, gli obblighi per i modelli di uso generale dall’agosto 2025; per i sistemi ad alto rischio una modifica approvata nel 2026 ha spostato le scadenze al dicembre 2027 (agosto 2028 per quelli inseriti in prodotti già regolati). Classifica i sistemi per **livello di rischio**: inaccettabile (vietati), alto, limitato, minimo.', 'The **AI Act** is the EU regulation on artificial intelligence, in force since 2024 and applied in stages: the bans apply from February 2025, the duties for general-purpose models from August 2025; for high-risk systems an amendment adopted in 2026 moved the deadlines to December 2027 (August 2028 for those built into already regulated products). It classifies systems by **risk level**: unacceptable (banned), high, limited, minimal.'),
            Fig(L(fig_aiethics_pyramid('inaccettabile', 'punteggio sociale, manipolazione', 'vietati', 'alto', 'personale, credito, istruzione', 'requisiti rigorosi', 'limitato', 'chatbot, contenuti generati', 'trasparenza', 'minimo', 'antispam, videogiochi', 'nessun obbligo specifico'), fig_aiethics_pyramid('unacceptable', 'social scoring, manipulation', 'banned', 'high', 'hiring, credit, education', 'strict requirements', 'limited', 'chatbots, generated content', 'transparency', 'minimal', 'spam filters, video games', 'no specific duty')),
                L('Una piramide a quattro livelli. In cima, il più stretto, il rischio inaccettabile: sistemi vietati, come il punteggio sociale. Poi il rischio alto, con requisiti rigorosi (selezione del personale, credito). Poi il rischio limitato, con obblighi di trasparenza (chatbot). Alla base, il più largo, il rischio minimo, senza obblighi specifici (filtri antispam).', 'A four-level pyramid. At the top, the narrowest, unacceptable risk: banned systems, such as social scoring. Then high risk, with strict requirements (hiring, credit). Then limited risk, with transparency duties (chatbots). At the base, the widest, minimal risk, with no specific duties (spam filters).'),
                L('Più sale il rischio, più pesano gli obblighi; la maggior parte dei sistemi sta alla base.', 'The higher the risk, the heavier the duties; most systems sit at the base.')),
            C('Inaccettabile  punteggio sociale dei cittadini, manipolazione → vietati
Alto           selezione del personale, credito, istruzione → requisiti rigorosi
Limitato       chatbot, contenuti generati → obblighi di trasparenza
Minimo         filtri antispam, videogiochi → nessun obbligo specifico', 'text'),
            P('Per i sistemi ad alto rischio servono gestione del rischio, dati di qualità, documentazione, supervisione umana. Per i chatbot e i contenuti generati l’obbligo principale è la **trasparenza**: le persone devono sapere che parlano con una macchina e che un contenuto è artificiale.', 'High-risk systems need risk management, quality data, documentation and human oversight. For chatbots and generated content the main duty is **transparency**: people must know they are talking to a machine and that content is artificial.'),
        ], [
            Q('a1', L('Su che cosa si basa l’AI Act?', 'What is the AI Act based on?'), [L('Livelli di rischio', 'Risk levels'), L('La dimensione dell’azienda', 'Company size'), L('Il prezzo del servizio', 'The service price'), L('Il linguaggio di programmazione', 'The programming language')], 0, L('Più rischio, più obblighi.', 'More risk, more duties.')),
            Q('a2', L('Il punteggio sociale dei cittadini è…', 'Social scoring of citizens is…'), [L('Vietato', 'Banned'), L('Rischio minimo', 'Minimal risk'), L('Senza obblighi', 'Without duties'), L('Consigliato', 'Recommended')], 0, L('Rischio inaccettabile.', 'Unacceptable risk.')),
            Q('a3', L('Quale obbligo principale ha un chatbot?', 'What is a chatbot’s main duty?'), [L('Dire che è una macchina', 'Saying it is a machine'), L('Essere gratuito', 'Being free'), L('Rispondere in latino', 'Answering in Latin'), L('Nessuno', 'None')], 0, L('Trasparenza.', 'Transparency.')),
        ], task('text', L('Classifica tre sistemi secondo l’AI Act, uno per riga come `sistema: rischio`. Sistemi: `filtro antispam`, `selezione dei curriculum`, `chatbot di assistenza`. Rischi: minimo, alto, limitato.', 'Classify three systems under the AI Act, one per line as `system: risk`. Systems: `spam filter`, `CV screening`, `support chatbot`. Risks: minimal, high, limited.'), '', [re('(antispam|spam)[^:\n]*:\s*(minimo|minimal)', L('Lo spam è rischio minimo', 'Spam is minimal risk')), re('(curricul|CV)[^:\n]*:\s*(alto|high)', L('La selezione è ad alto rischio', 'Screening is high risk')), re('chatbot[^:\n]*:\s*(limitato|limited)', L('Il chatbot è rischio limitato', 'The chatbot is limited risk'))], '', "filtro antispam: minimo\nselezione dei curriculum: alto\nchatbot di assistenza: limitato"), [
            dOrder(pSort(), [L('Inaccettabile', 'Unacceptable'), L('Alto', 'High'), L('Limitato', 'Limited'), L('Minimo', 'Minimal')], L('Dal più al meno rischioso.', 'From most to least risky.')),
            dMatch(pMatch(), [[L('Punteggio sociale', 'Social scoring'), L('Vietato', 'Banned')], [L('Selezione del personale', 'Recruitment'), L('Alto rischio', 'High risk')], ['Chatbot', L('Trasparenza', 'Transparency')], [L('Videogioco', 'Video game'), L('Rischio minimo', 'Minimal risk')]], L('Ogni sistema il suo livello.', 'Each system its level.')),
        ]),
        lesson('habits', L('Buone abitudini', 'Good habits'), [
            P('Qualche regola semplice per usare l’AI ogni giorno: **verifica** fatti, numeri e citazioni; **proteggi** dati tuoi e altrui; **dichiara** l’uso quando conta; **resta tu** il responsabile del risultato finale.', 'A few simple rules for everyday AI use: **verify** facts, numbers and quotes; **protect** your data and others’; **disclose** use when it matters; **stay** responsible for the final result.'),
            P('Attenzione anche ai **deepfake** (immagini, voci e video falsi): diffida di messaggi urgenti con voci conosciute che chiedono soldi o dati, e verifica sempre per un altro canale.', 'Watch out for **deepfakes** too (fake images, voices and videos): distrust urgent messages with familiar voices asking for money or data, and always verify through another channel.'),
            Tip('Una regola d’oro: non delegare all’AI una decisione che non sapresti spiegare o difendere tu.', 'A golden rule: do not delegate to AI a decision you could not explain or defend yourself.'),
        ], [
            Q('g1', L('Chi è responsabile di un testo pubblicato scritto con l’AI?', 'Who is responsible for a published text written with AI?'), [L('Chi lo pubblica', 'Whoever publishes it'), L('Il modello', 'The model'), L('Nessuno', 'Nobody'), L('Il fornitore di internet', 'The internet provider')], 0, L('Lo strumento non firma.', 'The tool does not sign.')),
            Q('g2', L('Ricevi un vocale urgente di un parente che chiede soldi: che fai?', 'You get an urgent voice message from a relative asking for money: what do you do?'), [L('Verifico chiamandolo su un altro canale', 'Verify by calling them on another channel'), L('Pago subito', 'Pay at once'), L('Inoltro a tutti', 'Forward it to everyone'), L('Rispondo con i dati della carta', 'Reply with card details')], 0, L('Le voci si possono clonare.', 'Voices can be cloned.')),
            Q('g3', L('Che cos’è un deepfake?', 'What is a deepfake?'), [L('Un contenuto falso realistico generato con l’AI', 'A realistic fake made with AI'), L('Un tipo di database', 'A kind of database'), L('Un antivirus', 'An antivirus'), L('Un errore di stampa', 'A typo')], 0, L('Immagini, voci, video.', 'Images, voices, videos.')),
        ], task('text', L('Scrivi la tua checklist personale per l’uso dell’AI: quattro righe che iniziano con `[ ]`, una sulla verifica e una sui dati.', 'Write your personal AI-use checklist: four lines starting with `[ ]`, one about verification and one about data.'), "[ ] \n[ ] \n[ ] \n[ ] ", [re('^\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S', L('Quattro voci', 'Four items')), re('verific|controll|check|verify', L('Una voce sulla verifica', 'An item on verification')), re('dati|privacy|personal|data', L('Una voce sui dati', 'An item on data'))], '', "[ ] verifico fatti e numeri importanti\n[ ] non inserisco dati personali di altri\n[ ] dichiaro l’uso dell’AI quando serve\n[ ] rileggo sempre prima di pubblicare"), [
            dMatch(pMatch(), [[L('Verifica', 'Verify'), L('Fatti, numeri, citazioni', 'Facts, numbers, quotes')], [L('Proteggi', 'Protect'), L('Dati tuoi e altrui', 'Your and others’ data')], [L('Dichiara', 'Disclose'), L('Uso dell’AI quando conta', 'AI use when it matters')], [L('Rispondi', 'Own it'), L('La responsabilità resta tua', 'Responsibility stays yours')]], L('Quattro abitudini.', 'Four habits.')),
            dFlash(pFlash(), [[L('Una voce al telefono può essere generata dall’AI', 'A voice on the phone can be AI-generated'), true], [L('Se l’ha scritto l’AI, la colpa non è mai tua', 'If AI wrote it, it is never your fault'), false], [L('Verificare per un altro canale protegge dalle truffe', 'Verifying through another channel protects from scams'), true], [L('Le immagini realistiche sono sempre vere', 'Realistic images are always real'), false]], L('Prudenza digitale.', 'Digital prudence.')),
        ]),
        lesson('labels', L('Etichettare i contenuti generati', 'Labelling generated content'), [
            P('Immagini, voci e testi generati sono ormai difficili da distinguere da quelli veri. Per questo si diffondono tre strumenti: le **etichette** visibili (“immagine generata con l’AI”), le **filigrane invisibili** inserite nei file dal generatore e le **credenziali di contenuto** (come lo standard C2PA), metadati firmati che raccontano come è nato e come è stato modificato un file.', 'Generated images, voices and texts are now hard to tell from real ones. That is why three tools are spreading: visible **labels** (“AI-generated image”), **invisible watermarks** embedded in files by the generator, and **content credentials** (such as the C2PA standard), signed metadata telling how a file was created and edited.'),
            P('Anche l’AI Act chiede trasparenza: chi crea deepfake deve dichiararli, e i sistemi che generano contenuti devono marcarli in un formato leggibile dalle macchine. Nessuno strumento è infallibile: i metadati si possono togliere e le filigrane a volte si rovinano. Per una notizia importante conta ancora la **fonte**: chi l’ha pubblicata e dove altro è confermata.', 'The AI Act also requires transparency: whoever creates deepfakes must disclose them, and systems generating content must mark it in a machine-readable format. No tool is foolproof: metadata can be stripped and watermarks sometimes get damaged. For important news the **source** still matters: who published it and where else it is confirmed.'),
        ], [
            Q('t1', L('Che cosa sono le credenziali di contenuto (C2PA)?', 'What are content credentials (C2PA)?'), [L('Una password per scaricare le immagini', 'A password to download images'), L('Un filtro che rende le foto più nitide', 'A filter that sharpens photos'), L('Metadati firmati sull’origine e le modifiche di un file', 'Signed metadata on a file’s origin and edits'), L('Un archivio pubblico di tutti i deepfake', 'A public archive of all deepfakes')], 2, L('Raccontano la storia del file.', 'They tell the file’s story.')),
            Q('t2', L('Una filigrana invisibile garantisce sempre di riconoscere un contenuto generato?', 'Does an invisible watermark always guarantee spotting generated content?'), [L('Sì, non si può mai togliere né rovinare', 'Yes, it can never be removed or damaged'), L('No, a volte si rovina o manca del tutto', 'No, it is sometimes damaged or missing'), L('Sì, ma solo per i testi', 'Yes, but only for text'), L('Sì, se l’immagine è a colori', 'Yes, if the image is in colour')], 1, L('Aiuta, non basta.', 'It helps, it is not enough.')),
            Q('t3', L('Che cosa chiede l’AI Act a chi pubblica un deepfake?', 'What does the AI Act ask of whoever publishes a deepfake?'), [L('Di dichiarare che è artificiale', 'To disclose that it is artificial'), L('Di pagare una tassa per ogni immagine', 'To pay a tax for each image'), L('Di pubblicarlo solo di notte', 'To publish it only at night'), L('Niente, i deepfake sono liberi', 'Nothing, deepfakes are unrestricted')], 0, L('Trasparenza verso chi guarda.', 'Transparency towards viewers.')),
        ], task('text', L('Scrivi la didascalia per un’immagine generata da pubblicare sui social: deve dire che è **generata** con l’AI e con quale **scopo**.', 'Write the caption for a generated image to post on social media: it must say it is **generated** with AI and for what **purpose**.'), '', [re('generat|creat|realizzat|made', L('Dici che è generata', 'You say it is generated')), re('\bAI\b|\bIA\b|intelligenza artificiale|artificial intelligence', L('Citi l’AI', 'You mention AI')), re('per |scopo|illustr|esempio|for |purpose|example', L('Indichi lo scopo', 'You state the purpose'))], '', 'Immagine generata con l’AI per illustrare l’articolo: non ritrae persone o luoghi reali.'), [
            dMatch(pMatch(), [[L('Etichetta', 'Label'), L('Avviso visibile', 'Visible notice')], [L('Filigrana invisibile', 'Invisible watermark'), L('Segnale nascosto nel file', 'Hidden signal in the file')], ['C2PA', L('Storia firmata del file', 'Signed history of the file')], [L('Fonte', 'Source'), L('Chi pubblica e conferma', 'Who publishes and confirms')]], L('Strumenti di trasparenza.', 'Transparency tools.')),
            dFlash(pFlash(), [[L('I metadati di un file si possono togliere', 'A file’s metadata can be stripped'), true], [L('Ogni contenuto generato porta sempre una filigrana', 'Every generated content always carries a watermark'), false], [L('Chi crea un deepfake deve dichiararlo', 'Whoever creates a deepfake must disclose it'), true], [L('Una foto realistica è prova sufficiente di un fatto', 'A realistic photo is enough proof of an event'), false]], L('Fidarsi delle fonti, non delle apparenze.', 'Trust sources, not appearances.')),
        ]),
        lesson('decisions', L('Decisioni automatiche e diritti', 'Automated decisions and rights'), [
            P('Quando un algoritmo decide su una persona (un prestito, un’assunzione, un sussidio) entrano in gioco i suoi **diritti**. Il GDPR dà il diritto di non essere sottoposti a decisioni **solo automatiche** con effetti importanti, salvo eccezioni, e di ottenere un intervento umano, esprimere la propria opinione e contestare la decisione.', 'When an algorithm decides about a person (a loan, a hire, a benefit) their **rights** come into play. The GDPR gives the right not to be subject to **solely automated** decisions with significant effects, with some exceptions, and to obtain human intervention, express one’s view and contest the decision.'),
            P('Per questo servono **spiegabilità** (poter dire perché il sistema ha deciso così, in parole comprensibili) e una **supervisione umana vera**: una persona che ha il tempo, le informazioni e l’autorità per cambiare la decisione. Se l’operatore approva tutto senza guardare, il controllo umano è solo di facciata.', 'That is why you need **explainability** (being able to say why the system decided as it did, in plain words) and **real human oversight**: a person with the time, information and authority to change the decision. If the operator approves everything without looking, the human check is only for show.'),
            C('Domanda di prestito respinta.
Motivi principali: reddito dichiarato basso rispetto alla rata (peso alto),
due ritardi di pagamento negli ultimi 12 mesi (peso medio).
Puoi chiedere che un operatore riesamini la domanda: richieste@banca.example', 'text'),
        ], [
            Q('d1', L('Che diritto dà il GDPR davanti a una decisione solo automatica e importante?', 'What right does the GDPR give against an important, solely automated decision?'), [L('Il diritto a un rimborso automatico', 'The right to an automatic refund'), L('Nessuno: l’algoritmo ha sempre ragione', 'None: the algorithm is always right'), L('Il diritto di cancellare l’algoritmo', 'The right to delete the algorithm'), L('Ottenere un intervento umano e contestarla', 'Obtaining human intervention and contesting it')], 3, L('Salvo alcune eccezioni previste.', 'Save for some set exceptions.')),
            Q('d2', L('Quando la supervisione umana è solo di facciata?', 'When is human oversight only for show?'), [L('Quando l’operatore approva tutto senza guardare', 'When the operator approves everything without looking'), L('Quando l’operatore può cambiare la decisione', 'When the operator can change the decision'), L('Quando l’operatore ha le informazioni necessarie', 'When the operator has the information needed'), L('Quando l’operatore ha il tempo di valutare', 'When the operator has time to assess')], 0, L('Serve potere vero di cambiare l’esito.', 'Real power to change the outcome is needed.')),
            Q('d3', L('Che cos’è la spiegabilità?', 'What is explainability?'), [L('Pubblicare tutto il codice sorgente del modello', 'Publishing all the model’s source code'), L('Dire in parole chiare perché il sistema ha deciso così', 'Saying in plain words why the system decided that way'), L('Rendere il modello più veloce a rispondere', 'Making the model answer faster'), L('Tradurre la decisione in più lingue', 'Translating the decision into several languages')], 1, L('Comprensibile per chi la riceve.', 'Understandable to whoever receives it.')),
        ], task('text', L('Scrivi un breve messaggio per un cliente il cui rimborso è stato respinto da un sistema automatico: indica un **motivo** e come chiedere una **revisione umana**.', 'Write a short message for a customer whose refund was rejected by an automated system: give a **reason** and how to ask for a **human review**.'), '', [re('motiv|perché|reason|because|dovuto', L('C’è un motivo', 'There is a reason')), re('operator|persona|umano|revision|riesam|human|review|staff', L('Offri una revisione umana', 'You offer a human review'))], '', 'Il rimborso è stato respinto perché la richiesta è arrivata dopo 60 giorni dall’acquisto. Puoi chiedere che un operatore riesamini il caso rispondendo a questo messaggio.'), [
            dMatch(pMatch(), [[L('Decisione solo automatica', 'Solely automated decision'), L('Nessuna persona coinvolta', 'No person involved')], [L('Spiegabilità', 'Explainability'), L('Il perché in parole chiare', 'The why in plain words')], [L('Supervisione umana', 'Human oversight'), L('Potere di cambiare l’esito', 'Power to change the outcome')], [L('Contestare', 'Contest'), L('Chiedere un riesame', 'Ask for a review')]], L('Le persone prima degli algoritmi.', 'People before algorithms.')),
            dFlash(pFlash(), [[L('Una persona può contestare una decisione automatica importante', 'A person can contest an important automated decision'), true], [L('Un operatore che approva tutto è una vera supervisione', 'An operator approving everything is real oversight'), false], [L('Spiegare i motivi aiuta a contestare un errore', 'Explaining the reasons helps contest a mistake'), true], [L('Il GDPR non riguarda le decisioni automatiche', 'The GDPR does not cover automated decisions'), false]], L('Decidere in modo responsabile.', 'Deciding responsibly.')),
        ]),
        lesson('impact', L('Impatto su ambiente e lavoro', 'Impact on environment and work'), [
            P('Addestrare e usare grandi modelli richiede molta **energia** e **acqua** per raffreddare i data center, e hardware che va prodotto e smaltito. Ogni singola richiesta consuma poco, ma miliardi di richieste pesano. Scelte semplici aiutano: usare un modello piccolo quando basta, evitare generazioni inutili, preferire fornitori che dichiarano consumi e fonti rinnovabili.', 'Training and running large models takes a lot of **energy** and **water** to cool data centres, plus hardware that must be made and disposed of. Each single request uses little, but billions of requests add up. Simple choices help: using a small model when it is enough, avoiding pointless generations, preferring providers that disclose consumption and renewable sources.'),
            P('Sul **lavoro** l’AI cambia soprattutto i **compiti** più che sostituire mestieri interi: automatizza bozze, ricerche e lavori ripetitivi, e rende più importanti giudizio, verifica e relazioni. Chi impara a usarla bene ne trae vantaggio; le organizzazioni responsabili formano le persone (l’AI Act chiede anche un’adeguata **alfabetizzazione sull’AI**) invece di lasciarle indietro.', 'At **work** AI mostly changes **tasks** rather than replacing whole jobs: it automates drafts, research and repetitive work, and makes judgement, checking and relationships more important. People who learn to use it well gain from it; responsible organisations train their people (the AI Act also calls for adequate **AI literacy**) instead of leaving them behind.'),
        ], [
            Q('i1', L('Perché i data center consumano acqua?', 'Why do data centres use water?'), [L('Per lavare i dischi rigidi ogni giorno', 'To wash the hard disks every day'), L('Per produrre l’elettricità sul posto', 'To generate electricity on site'), L('Per raffreddare i server', 'To cool the servers'), L('Per stampare i risultati dei modelli', 'To print the models’ results')], 2, L('Il calcolo produce calore.', 'Computing produces heat.')),
            Q('i2', L('Che cosa cambia di più l’AI nel lavoro, secondo l’esperienza finora?', 'What does AI change most at work, judging by experience so far?'), [L('Singoli compiti più che mestieri interi', 'Single tasks more than whole jobs'), L('Nulla, perché nessuno la usa', 'Nothing, because nobody uses it'), L('Solo il lavoro dei programmatori', 'Only programmers’ work'), L('Sostituisce subito tutti i mestieri', 'It replaces every job at once')], 0, L('Bozze, ricerche, lavori ripetitivi.', 'Drafts, research, repetitive work.')),
            Q('i3', L('Quale scelta riduce l’impatto ambientale dell’uso dell’AI?', 'Which choice reduces the environmental impact of using AI?'), [L('Generare dieci versioni di ogni testo', 'Generating ten versions of every text'), L('Usare un modello piccolo quando basta', 'Using a small model when it is enough'), L('Usare sempre il modello più grande', 'Always using the largest model'), L('Ripetere la stessa domanda più volte', 'Repeating the same question several times')], 1, L('Lo strumento giusto, senza sprechi.', 'The right tool, without waste.')),
        ], task('text', L('Scrivi due buone pratiche per usare l’AI con meno impatto, una per riga che inizia con `-`.', 'Write two good practices for using AI with less impact, one per line starting with `-`.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due pratiche', 'Two practices')), re('piccol|small|inutil|pointless|unnecessar|evita|avoid|meno|fewer|less|rinnovabil|renewable', L('Una riduce consumi o sprechi', 'One cuts consumption or waste'))], '', "- usare un modello piccolo per i compiti semplici\n- evitare di rigenerare risposte inutili"), [
            dMatch(pMatch(), [[L('Energia', 'Energy'), L('Alimenta il calcolo', 'Powers computation')], [L('Acqua', 'Water'), L('Raffredda i server', 'Cools servers')], [L('Compiti', 'Tasks'), L('Ciò che l’AI cambia di più', 'What AI changes most')], [L('Alfabetizzazione AI', 'AI literacy'), L('Formare le persone', 'Training people')]], L('Gli effetti oltre lo schermo.', 'Effects beyond the screen.')),
            dFlash(pFlash(), [[L('Miliardi di piccole richieste hanno un impatto reale', 'Billions of small requests have a real impact'), true], [L('L’AI non consuma energia', 'AI uses no energy'), false], [L('Formare le persone aiuta ad adottare l’AI bene', 'Training people helps adopt AI well'), true], [L('Il modello più grande è sempre il più sostenibile', 'The largest model is always the most sustainable'), false]], L('Usarla con misura.', 'Using it in moderation.')),
        ]),
    ],
];
